class FieldDefinition {
  constructor(type, { stored = false } = {}) {
    this.type = type;
    this.stored = stored;
  }
}

export function TEXT(options = {}) {
  return new FieldDefinition('TEXT', options);
}

export function ID(options = {}) {
  return new FieldDefinition('ID', options);
}

export function NUMERIC(options = {}) {
  return new FieldDefinition('NUMERIC', options);
}

export class Schema {
  constructor(definition) {
    this.definition = { ...definition };
  }

  getField(name) {
    return this.definition[name] ?? null;
  }

  hasField(name) {
    return Object.prototype.hasOwnProperty.call(this.definition, name);
  }
}

