  'this',
  'to',
  'us',
  'we',
  'when',
  'will',
  'with',
  'yet',
  'you',
  'your',
]);

const TOKEN_PATTERN = /[A-Za-z0-9_]+(?:\.[A-Za-z0-9_]+)*/g;

export function analyzeText(value) {
  if (value === null || value === undefined) {
    return [];
  }

  const text = String(value).toLowerCase();
  const matches = text.match(TOKEN_PATTERN) ?? [];
  return matches.filter((token) => !STOP_WORDS.has(token));
}

export function hasPhrase(fieldValue, phraseValue) {
  const haystack = analyzeText(fieldValue);
  const needle = analyzeText(phraseValue);

  if (needle.length === 0 || needle.length > haystack.length) {
    return false;
  }

  for (let index = 0; index <= haystack.length - needle.length; index += 1) {
    let matched = true;
    for (let offset = 0; offset < needle.length; offset += 1) {
      if (haystack[index + offset] !== needle[offset]) {
        matched = false;
        break;
      }
    }
    if (matched) {
      return true;
    }
  }

  return false;
}

export function wildcardToRegExp(pattern) {
  const escaped = pattern
    .toLowerCase()
    .replace(/[|\\{}()[\]^$+?.]/g, '\\$&')
    .replace(/\\\*/g, '.*')
    .replace(/\\\?/g, '.');
  return new RegExp(`^${escaped}$`);
}

