import { executeQuery } from './query.mjs';

class Writer {
  constructor(index) {
    this.index = index;
    this.pending = [];
  }

  add_document(document) {
    this.pending.push({ ...document });
  }

  commit() {
    this.index.documents.push(...this.pending);
    this.pending = [];
  }
}

class Searcher {
  constructor(index) {
    this.index = index;
  }

  search(query, { limit = 10 } = {}) {
    const docIds = executeQuery(query, this.index.documents, this.index.schema);
    const results = [];

    for (let index = 0; index < this.index.documents.length; index += 1) {
      if (docIds.has(index)) {
        results.push(this.index.documents[index]);
      }
      if (results.length >= limit) {
        break;
      }
    }

    return results;
  }
}

class InMemoryIndex {
  constructor(schema) {
    this.schema = schema;
    this.documents = [];
  }

  writer() {
    return new Writer(this);
  }

  searcher() {
    return new Searcher(this);
  }
}

export function createIn(_directory, schema) {
  return new InMemoryIndex(schema);
}

