import { isPythonIntLiteral, parsePythonInt } from './pyint.mjs';

const PROGRAM_NAME = 'test15_executable';
const USAGE = `usage: ${PROGRAM_NAME} [-h] --a A --b B --c C\n`;
const HELP = `${USAGE}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n`;

const ARGUMENTS = [
  ['--a', { name: 'a', type: 'str' }],
  ['--b', { name: 'b', type: 'int' }],
  ['--c', { name: 'c', type: 'int' }],
];

const ARGUMENT_MAP = new Map(ARGUMENTS);

function writeAndExit(stream, message, code) {
  stream.write(message);
  process.exit(code);
}

function error(message) {
  writeAndExit(process.stderr, `${USAGE}${PROGRAM_NAME}: error: ${message}\n`, 2);
}

function normalizeOption(token) {
  if (!token.startsWith('--')) {
    return { option: token, attachedValue: null };
  }

  const equalsIndex = token.indexOf('=');
  if (equalsIndex === -1) {
    return { option: token, attachedValue: null };
  }

  return {
    option: token.slice(0, equalsIndex),
    attachedValue: token.slice(equalsIndex + 1),
  };
}

function readValue(option, spec, attachedValue, nextToken) {
  if (attachedValue !== null) {
    return attachedValue;
  }

  if (nextToken === undefined) {
    error(`argument ${option}: expected one argument`);
  }

  if (
    spec.type === 'str' &&
    nextToken.startsWith('-') &&
    nextToken !== '-'
  ) {
    error(`argument ${option}: expected one argument`);
  }

  if (
    spec.type === 'int' &&
    nextToken.startsWith('-') &&
    nextToken !== '-' &&
    !isPythonIntLiteral(nextToken)
  ) {
    error(`argument ${option}: expected one argument`);
  }

  return nextToken;
}

export function parseArgsOrExit(argv = process.argv.slice(2)) {
  const parsed = { a: undefined, b: undefined, c: undefined };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      writeAndExit(process.stdout, HELP, 0);
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    const { option, attachedValue } = normalizeOption(token);
    const spec = ARGUMENT_MAP.get(option);

    if (!spec) {
      extras.push(token);
      continue;
    }

    const consumesNext = attachedValue === null;
    const value = readValue(option, spec, attachedValue, argv[index + 1]);
    if (consumesNext) {
