      const parsedValue = parsePythonInt(value);
      if (parsedValue === null) {
        error(`argument ${option}: invalid int value: '${value}'`);
      }
      parsed[spec.name] = parsedValue;
      continue;
    }

    parsed[spec.name] = value;
