      const fieldScoped = this.parsePrimary(token.field);
      if (fieldScoped.type !== 'null') {
        return fieldScoped;
      }
      return buildTextNode(defaultField, token.field);
    }

    if (token.type === 'LPAREN') {
      this.consume();
      const group = this.parseOr(defaultField);
      if (this.current().type === 'RPAREN') {
        this.consume();
      }
      return group;
    }

    if (token.type === 'PHRASE') {
      this.consume();
      return buildPhraseNode(defaultField, token.value);
    }

    if (token.type === 'RANGE') {
      this.consume();
      return buildRangeNode(defaultField, this.schema.get(defaultField), token);
    }

    if (token.type === 'TERM') {
      this.consume();
      return this.parseTerm(defaultField, token.value);
    }

    return NULL_QUERY;
  }

  parseTerm(defaultField, rawValue) {
    const normalized = normalizeRawTerm(rawValue);
    if (normalized.length === 0) {
      return NULL_QUERY;
    }

    const fieldMatch = normalized.match(/^([A-Za-z_][A-Za-z0-9_]*):(.*)$/s);
    if (fieldMatch && this.fieldNames.has(fieldMatch[1])) {
      const fieldName = fieldMatch[1];
      const rhs = fieldMatch[2];
      if (rhs.length === 0) {
        return buildTextNode(defaultField, fieldName);
      }

      const nested = new InternalParser(fieldName, this.schema, rhs).parse();
      return nested.type === 'null' ? buildTextNode(defaultField, fieldName) : nested;
    }

    return buildTermNode(defaultField, this.schema.get(defaultField), normalized);
  }
}

class ParsedQuery {
  constructor(ast) {
    this.ast = ast;
  }

  matches(document) {
    return evaluateNode(this.ast, document);
  }
}

export class QueryParser {
  constructor(defaultField, schema) {
    this.defaultField = defaultField;
    this.schema = schema;
  }

  parse(text) {
    const ast = new InternalParser(this.defaultField, this.schema, String(text ?? '')).parse();
    return new ParsedQuery(ast);
  }
}

