import { basename } from 'node:path';

const USAGE_SUFFIX = '[-h] --a A --b B --c C';

function usage(programName) {
  return `usage: ${programName} ${USAGE_SUFFIX}`;
}

function help(programName) {
  return `${usage(programName)}

options:
  -h, --help  show this help message and exit
  --a A
  --b B
  --c C`;
}

function writeStderr(text) {
  process.stderr.write(`${text}\n`);
}

function fail(programName, message) {
  writeStderr(usage(programName));
  writeStderr(`${programName}: error: ${message}`);
  process.exit(2);
}

function isIntegerLiteral(value) {
  return /^[+-]?\d+$/.test(value);
}

function parseInteger(flag, rawValue, programName) {
  if (!isIntegerLiteral(rawValue)) {
    fail(programName, `argument ${flag}: invalid int value: '${rawValue}'`);
  }

  return Number.parseInt(rawValue, 10);
}

function looksLikeMissingValue(rawValue, type) {
  if (rawValue === undefined || rawValue === '--') {
    return true;
  }

  if (type === 'int' && isIntegerLiteral(rawValue)) {
    return false;
  }

  if (rawValue.includes(' ')) {
    return false;
  }

  return rawValue.startsWith('-');
}

function parseOptionValue(flag, type, argv, index, programName) {
  const rawValue = argv[index + 1];
  if (looksLikeMissingValue(rawValue, type)) {
    fail(programName, `argument ${flag}: expected one argument`);
  }

  if (type === 'int') {
    return { value: parseInteger(flag, rawValue, programName), nextIndex: index + 1 };
  }

  return { value: rawValue, nextIndex: index + 1 };
}

function parseInlineValue(flag, type, rawValue, programName) {
  if (type === 'int') {
    return parseInteger(flag, rawValue, programName);
  }

  return rawValue;
}

export function parseCommandLine(argv) {
  const programName = basename(argv[1] ?? 'test15.mjs');
  const parsed = { a: undefined, b: undefined, c: undefined };
  const unknown = [];

  for (let index = 2; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      process.stdout.write(`${help(programName)}\n`);
      process.exit(0);
    }

    if (token === '--') {
      unknown.push(...argv.slice(index + 1));
      break;
    }

    if (token === '--a') {
      const parsedValue = parseOptionValue('--a', 'string', argv, index, programName);
      parsed.a = parsedValue.value;
      index = parsedValue.nextIndex;
      continue;
    }

    if (token === '--b') {
      const parsedValue = parseOptionValue('--b', 'int', argv, index, programName);
      parsed.b = parsedValue.value;
      index = parsedValue.nextIndex;
      continue;
    }

    if (token === '--c') {
      const parsedValue = parseOptionValue('--c', 'int', argv, index, programName);
      parsed.c = parsedValue.value;
      index = parsedValue.nextIndex;
      continue;
    }

    if (token.startsWith('--a=')) {
      parsed.a = parseInlineValue('--a', 'string', token.slice(4), programName);
      continue;
    }

    if (token.startsWith('--b=')) {
      parsed.b = parseInlineValue('--b', 'int', token.slice(4), programName);
      continue;
    }

    if (token.startsWith('--c=')) {
      parsed.c = parseInlineValue('--c', 'int', token.slice(4), programName);
      continue;
    }

    unknown.push(token);
  }

  const missing = [];
  if (parsed.a === undefined) {
    missing.push('--a');
  }
  if (parsed.b === undefined) {
    missing.push('--b');
  }
  if (parsed.c === undefined) {
    missing.push('--c');
  }

  if (missing.length > 0) {
    fail(programName, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (unknown.length > 0) {
    fail(programName, `unrecognized arguments: ${unknown.join(' ')}`);
  }

  return parsed;
}

