import { parseArgsOrExit } from './lib/argparse.mjs';
import { Schema, TEXT, NUMERIC } from './lib/miniwhoosh/fields.mjs';
import { createIn } from './lib/miniwhoosh/index.mjs';
import { QueryParser } from './lib/miniwhoosh/query.mjs';

export function main() {
  const args = parseArgsOrExit();

  const schema = new Schema({
    title: TEXT({ stored: true }),
    price: NUMERIC({ stored: true }),
    content: TEXT(),
  });

  const tempDir = '/tmp/test15';
  const index = createIn(tempDir, schema);
  const writer = index.writer();
  writer.add_document({ title: args.a, price: args.b, content: 'item1' });
  writer.add_document({ title: args.a, price: args.c, content: 'item2' });
  writer.commit();

  const searcher = index.searcher();
  const query = new QueryParser('title', index.schema).parse(args.a);
  const results = searcher.search(query, { limit: 10 });
  const totalPrice = results.reduce((sum, result) => sum + result.price, 0);

  process.stdout.write(`${totalPrice}\n`);
}

main();

